from pathlib import Path
import sys,json,time
sys.path.insert(0,str(Path(__file__).resolve().parent.parent/'rain-coupled-reference'))
import model as m
from wave import ops,project,wave,solve_pair
import numpy as np
from scipy.linalg import cho_factor,cho_solve
p=Path(__file__).resolve().parent;free=np.concatenate([np.arange(b['sl'].start,b['sl'].stop) for b in m.blocks if b['domain']=='free']);remaining=np.array([i for i in range(m.offset) if i not in set(free)]);lookup={i:k for k,i in enumerate(remaining)}
Hff=m.H[np.ix_(free,free)];Hfr=m.H[np.ix_(free,remaining)];Hrr=m.H[np.ix_(remaining,remaining)];factor=cho_factor(Hff,lower=True);base=-cho_solve(factor,m.g[free]);response=-cho_solve(factor,Hfr);S=Hrr+Hfr.T@response;S=(S+S.T)*.5;q=m.g[remaining]+Hfr.T@base

def recover(y):
 x=np.zeros(m.offset);x[remaining]=y;x[free]=base+response@y;return x
B=m.M@m.J.T;velocity_base=m.vfree+B[:,free]@base;velocity_response=B[:,remaining]+B[:,free]@response
rng=np.random.default_rng(20261002);errors=[]
for _ in range(24):
 y=rng.normal(size=len(remaining));x=recover(y);grad=m.gradient_primal(x);reduced=S@y+q
 errors.append(dict(free=float(np.max(abs(grad[free])/(1+abs(x[free])))),reduced=float(np.max(abs(grad[remaining]-reduced)/(1+np.maximum(abs(grad[remaining]),abs(reduced))))),velocity=float(np.max(abs(m.vfree+B@x-(velocity_base+velocity_response@y))))))
assert max(max(r.values()) for r in errors)<1e-10
reference=np.load(m.p/'polished-solution.npz');ref=reference['impulses'];recovered=recover(ref[remaining]);reference_difference=float(np.max(abs(recovered-ref)));reference_natural=float(np.max(abs(m.residual(recovered))/(1+abs(recovered))));assert reference_difference<1e-9 and reference_natural<1e-8
reduced_ops=[];ranks=[]
for op in ops:
 if op['domain']=='free':continue
 ii=np.array([lookup[int(i)] for i in op['indices']]);K=S[np.ix_(ii,ii)];eig,V=np.linalg.eigh(K);threshold=1e-12*max(1.,float(max(eig)));assert min(eig)>=-threshold
 ranks.append(dict(label=op['label'],size=len(ii),rank=int(sum(eig>threshold)),min_eigenvalue=float(min(eig)),max_eigenvalue=float(max(eig))))
 reduced_ops.append(dict(original=op,indices=ii,K=K,eigen=np.maximum(eig,0),V=V,threshold=threshold))
metadata=dict(free_dofs=len(free),remaining_dofs=len(remaining),free_min_eigenvalue=float(min(np.linalg.eigvalsh(Hff))),free_condition=float(np.linalg.cond(Hff)),controls=errors,reference_recovery_max_difference=reference_difference,reference_relative_natural_residual=reference_natural,local_block_ranks=ranks)
(p/'controls.json').write_text(json.dumps(metadata,indent=2));print('CONTROLS',json.dumps({k:v for k,v in metadata.items() if k not in ['controls','local_block_ranks']}),flush=True)

def ball(op,g,r,old):
 if r<=0:return old*0
 e,V=op['eigen'],op['V'];tol=op['threshold'];z=V.T@g;positive=e>tol;null=~positive
 if np.linalg.norm(z[null])<=1e-10*(1+np.linalg.norm(g)):
  z[null]=0;coords=np.zeros(len(g));coords[positive]=-z[positive]/e[positive];space=r*r-float(coords@coords)
  if space>=0:
   old_null=(V.T@old)[null];length=np.linalg.norm(old_null);coords[null]=old_null*min(1.,np.sqrt(space)/max(length,1e-300));return V@coords
 lo=0.;hi=np.linalg.norm(z)/r
 for _ in range(64):
  mid=.5*(lo+hi);candidate=-z/(e+mid)
  if np.linalg.norm(candidate)>r:lo=mid
  else:hi=mid
 return V@(-z/(e+hi))

def reduced_wave(y):
 y=y.copy();x=recover(y);velocity=velocity_base+velocity_response@y;max_v=max_i=0.;worst=None
 for op in reduced_ops:
  original=op['original'];ii=op['indices'];before=y[ii].copy();grad=S[ii]@y+q[ii];K=op['K'];domain=original['domain'];new=before.copy()
  if domain=='positive_pair':
   if np.linalg.det(K)>1e-5*K[0,0]*K[1,1]:new=solve_pair(K,grad-K@before)
   else:
    for local in range(2):
     assert K[local,local]>op['threshold'];new[local]=max(0.,new[local]-(grad[local]+K[local]@(new-before))/K[local,local])
  elif domain in ['positive','box']:
   assert len(ii)==1 and K[0,0]>op['threshold'];new=before-grad/K[0,0]
   if domain=='positive':new=np.maximum(new,0)
   else:new=np.clip(new,-m.radius(original,x),m.radius(original,x))
  else:assert domain=='ball';new=ball(op,grad-K@before,m.radius(original,x),before)
  delta=new-before;next_velocity=velocity+velocity_response[:,ii]@delta;next_x=x.copy();next_x[remaining[ii]]=new;next_x[free]+=response[:,ii]@delta
  vchange=float(np.max(abs(next_velocity-velocity)/(1+np.maximum(abs(next_velocity),abs(velocity)))));ichange=float(np.max(abs(next_x-x)/(1+np.maximum(abs(next_x),abs(x)))))
  if max(vchange,ichange)>max(max_v,max_i):worst=original['label']
  max_v=max(max_v,vchange);max_i=max(max_i,ichange);x=next_x;velocity=next_velocity;y[ii]=new
 return y,dict(max_velocity_change=max_v,max_impulse_change=max_i,worst_block=worst)

results={}
for name,initial in [('cold',np.zeros(m.offset)),('capped',m.old.copy())]:
 y=project(initial)[remaining];records=[];quiet=0;start=time.monotonic();terminal=False
 for iteration in range(128):
  next_y,stats=reduced_wave(y);quiet=quiet+1 if max(stats['max_velocity_change'],stats['max_impulse_change'])<=1e-5 else 0;y=next_y;x=recover(y);natural=float(np.max(abs(m.residual(x))/(1+abs(x))));records.append(dict(wave=iteration+1,relative_natural_residual=natural,**stats))
  if quiet>=2 and natural<=1e-8:terminal=True;break
 x=recover(y);_,full_wave=wave(x);feas=[]
 for b in m.blocks:
  val=x[b['sl']];domain=b['domain'];r=m.radius(b,x);error=0.
  if domain=='positive':error=max(0,-float(min(val)))
  elif domain=='box':error=max(0,float(max(abs(val)))-r)/(1+r)
  elif domain=='ball':error=max(0,float(np.linalg.norm(val))-r)/(1+r)
  feas.append(error)
 passed=bool(terminal and max(feas)<=1e-8 and max(full_wave['max_velocity_change'],full_wave['max_impulse_change'])<=1e-5)
 result=dict(status='prototype-pass' if passed else 'prototype-failed',waves=len(records),seconds=time.monotonic()-start,final_relative_natural_residual=natural,maximum_scaled_feasibility_violation=max(feas),original_colored_wave=full_wave,reference_velocity_max_difference=float(np.max(abs(m.vfree+B@x-reference['velocities']))),reference_impulse_max_difference=float(np.max(abs(x-ref))),history=records)
 results[name]=result;np.savez(p/(name+'-solution.npz'),impulses=x,velocities=m.vfree+B@x);(p/'result.json').write_text(json.dumps(dict(scope='Exact bilateral Schur reduction of the reconstructed model; serial native color/row ordering, not a GPU ownership/performance implementation.',arms=results),indent=2));print(name,json.dumps({k:v for k,v in result.items() if k!='history'}),flush=True)
if not all(r['status']=='prototype-pass' for r in results.values()):raise SystemExit(1)
